import { ref } from 'vue'

export const SUPPORTED_LANGS = ['zh', 'en']
const STORAGE_KEY = 'paperguard_lang'

function readLanguage() {
  const saved = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEY) : null
  if (SUPPORTED_LANGS.includes(saved)) return saved
  return 'zh'
}

export const currentLang = ref(readLanguage())

function formatMessage(value, params = {}) {
  return String(value).replace(/\{(\w+)\}/g, (match, key) => (
    params[key] === undefined || params[key] === null ? match : String(params[key])
  ))
}

export function translate(key, params = {}, lang = currentLang.value) {
  const locale = SUPPORTED_LANGS.includes(lang) ? lang : 'zh'
  const value = translations[locale][key] ?? translations.zh[key] ?? key
  return formatMessage(value, params)
}

/**
 * 角色标签统一入口。
 *
 * 不要用 `role === 'admin' ? t('role.admin') : t('role.college_admin')` 这种二元三元：
 * 它会把 teacher / student 一律显示成「学院管理员」。凡是渲染当前用户角色的地方都用这个函数。
 * 未收录的角色回落到 role.user，不把 key 本身漏给用户。
 */
export function roleLabel(role, lang = currentLang.value) {
  const locale = SUPPORTED_LANGS.includes(lang) ? lang : 'zh'
  return translations[locale][`role.${role}`]
    ?? translations.zh[`role.${role}`]
    ?? translations.zh['role.user']
}

export function useI18n() {
  function setLang(lang) {
    if (!SUPPORTED_LANGS.includes(lang)) return
    currentLang.value = lang
    if (typeof localStorage !== 'undefined') localStorage.setItem(STORAGE_KEY, lang)
  }

  function t(key, params = {}) {
    return translate(key, params, currentLang.value)
  }

  function formatDate(value, options = {}) {
    if (!value) return '-'
    try {
      return new Intl.DateTimeFormat(currentLang.value === 'zh' ? 'zh-CN' : 'en-US', options).format(new Date(value))
    } catch {
      return String(value)
    }
  }

  function formatNumber(value, options = {}) {
    return new Intl.NumberFormat(currentLang.value === 'zh' ? 'zh-CN' : 'en-US', options).format(Number(value || 0))
  }

  return { lang: currentLang, setLang, t, formatDate, formatNumber }
}

